INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "アヤネ", "2030/12/17 14:59:59", 24001, 2, "2020/07/31 12:00:00", 10046, 0.0, 401, 0.0, 24, 102301, 0.0, "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "アヤネ", "2030/12/17 14:59:59", 24002, 1, "2020/07/31 12:00:00", 10046, 0.0, 402, 0.0, 24, 102301, 2.21, "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "アヤネ", "2030/12/17 14:59:59", 24003, 2, "2020/07/31 12:00:00", 10046, 0.0, 403, 0.0, 24, 102301, 0.0, "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "アサヒ", "2030/12/17 14:59:59", 24004, 2, "2020/07/31 12:00:00", 10046, 0.0, 701, 0.0, 24, 192201, 1.99, "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "アサヒ", "2030/12/17 14:59:59", 24005, 1, "2020/07/31 12:00:00", 10046, 0.0, 702, 0.0, 24, 192201, 2.21, "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "アサヒ", "2030/12/17 14:59:59", 24006, 2, "2020/07/31 12:00:00", 10046, 0.0, 703, 0.0, 24, 192201, 3.33, "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "部員３", "2030/12/17 14:59:59", 24007, 2, "2020/07/31 12:00:00", 10046, 0.0, 801, 0.0, 24, 192301, 0.0, "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "部員３", "2030/12/17 14:59:59", 24008, 1, "2020/07/31 12:00:00", 10046, 0.0, 802, 0.0, 24, 192301, 2.68, "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "部員３", "2030/12/17 14:59:59", 24009, 2, "2020/07/31 12:00:00", 10046, 0.0, 803, 0.0, 24, 192301, 0.0, "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "", "2030/12/17 14:59:59", 24010, 1, "2020/07/31 12:00:00", 10046, 0.0, 501, 0.0, 24, 192501, 0.0, "やった！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "", "2030/12/17 14:59:59", 24011, 1, "2020/07/31 12:00:00", 10046, 0.0, 502, 0.0, 24, 192501, 0.0, "勝ったよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "", "2030/12/17 14:59:59", 24012, 1, "2020/07/31 12:00:00", 10046, 0.0, 503, 0.0, 24, 192501, 0.0, "いい調子！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24013, 6, "2020/07/31 12:00:00", 10046, 0.0, 111, 0.0, 24, 113501, 5.33, "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24014, 1, "2020/07/31 12:00:00", 10046, 0.0, 112, 0.0, 24, 113501, 6.85, "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24015, 1, "2020/07/31 12:00:00", 10046, 0.0, 113, 0.0, 24, 113501, 3.0, "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ダイチ", "2030/12/17 14:59:59", 24016, 1, "2020/07/31 12:00:00", 10046, 0.0, 611, 0.0, 24, 192401, 6.11, "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ダイチ", "2030/12/17 14:59:59", 24017, 1, "2020/07/31 12:00:00", 10046, 0.0, 612, 0.0, 24, 192401, 6.75, "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ダイチ", "2030/12/17 14:59:59", 24018, 2, "2020/07/31 12:00:00", 10046, 0.0, 613, 0.0, 24, 192401, 0.0, "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "ハツネ", "2030/12/17 14:59:59", 24019, 2, "2020/07/31 12:00:00", 10046, 0.0, 211, 0.0, 24, 113401, 4.52, "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "ハツネ", "2030/12/17 14:59:59", 24020, 2, "2020/07/31 12:00:00", 10046, 0.0, 212, 0.0, 24, 113401, 3.89, "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ハツネ", "2030/12/17 14:59:59", 24021, 1, "2020/07/31 12:00:00", 10046, 0.0, 213, 0.0, 24, 113401, 13.49, "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "カヤ", "2030/12/17 14:59:59", 24022, 1, "2020/07/31 12:00:00", 10046, 0.0, 311, 0.0, 24, 106501, 3.17, "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "カヤ", "2030/12/17 14:59:59", 24023, 1, "2020/07/31 12:00:00", 10046, 0.0, 312, 0.0, 24, 106501, 4.42, "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "カヤ", "2030/12/17 14:59:59", 24024, 6, "2020/07/31 12:00:00", 10046, 0.0, 313, 0.0, 24, 106501, 2.89, "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3, "アヤネ", "2030/12/17 14:59:59", 24025, 4, "2020/07/31 12:00:00", 10046, 0.0, 421, 0.0, 24, 102301, 3.71, "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "アサヒ", "2030/12/17 14:59:59", 24026, 2, "2020/07/31 12:00:00", 10046, 0.0, 721, 0.0, 24, 192201, 5.1, "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (3, "部員３", "2030/12/17 14:59:59", 24027, 1, "2020/07/31 12:00:00", 10046, 0.0, 821, 0.0, 24, 192301, 4.34, "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "", "2030/12/17 14:59:59", 24028, 1, "2020/07/31 12:00:00", 10046, 0.0, 521, 0.0, 24, 192501, 0.0, "いい勝負だったよ\nまたやろうね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24029, 1, "2020/07/31 12:00:00", 10046, 0.0, 101, -360.0, 24, 113501, 5.62, "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24030, 1, "2020/07/31 12:00:00", 10046, 0.0, 102, -360.0, 24, 113501, 9.58, "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24031, 2, "2020/07/31 12:00:00", 10046, 0.0, 103, -360.0, 24, 113501, 0.0, "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (1, "ミサト", "2030/12/17 14:59:59", 24032, 2, "2020/07/31 12:00:00", 10046, 0.0, 104, -360.0, 24, 113501, 9.13, "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！");
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES (2, "ミサト", "2030/12/17 14:59:59", 24033, 1, "2020/07/31 12:00:00", 10046, 0.0, 105, -360.0, 24, 113501, 8.27, "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！");
